//! Measured bodies for the bot mark, the same table as the web app's
//! `packages/core/src/avatars/bot-mark-body-data.ts`, in body units (the sphere's radius is 1.18 of
//! them at size 1). Generated from that file; edit it there and regenerate, not by hand.

use crate::mark::Shape;

pub(crate) enum Kind {
    /// A profile turned on a lathe: heights from `top` to `bottom` and a packed radius at each.
    Revolve { top: f64, bottom: f64, radii: &'static str, wrap: [f64; 3] },
    /// An outline pushed back `half_depth` either way with rounded edges; `None` is the flower.
    Extrusion { half_depth: f64, bevel: f64, convex: bool, face: f64, outline: Option<&'static str> },
    /// An outline puffed into a pillow.
    Loft { depth: f64, outline: &'static str },
    /// A slab with rounded edges.
    Slab { half_depth: f64, edge: f64, outline: &'static str, face: f64 },
    /// The rounded gem.
    Crystal { face: f64 },
    /// A row of balls along x (lying) or y (standing).
    Pill { lying: bool, reach: f64, radius: f64, seat: [f64; 3] },
    /// Overlapping balls, packed as x, y and radius.
    Balls { balls: &'static str, wrap: [f64; 3] },
}

pub(crate) struct Spec {
    pub size: f64,
    /// Eye width, eye height, the gap between the eyes, and how far down they sit.
    pub eyes: [f64; 4],
    pub kind: Kind,
}

